writing.exampleCode:
fn main() {
    let text = "é🦀";
    assert_eq!(text.len(), 6);
    assert_eq!(text.chars().count(), 2);
    assert_eq!(text.encode_utf16().count(), 3);
    assert_eq!(text.get(0..2), Some("é"));
    assert_eq!(text.get(1..2), None);
    assert_eq!("e\u{301}".chars().count(), 2);
}

